$BlockedJsonPath    = Join-Path $BaseDir "blocked-apps.json"
$CertPath           = Join-Path $CertDir "AcceleronCertificate.cer"
$LogFile            = Join-Path $BaseDir "AppLocker.log"

$RegPath            = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppLocker"

# Calculate folder size in KB
$EstimatedSize = [math]::Ceiling(((Get-ChildItem $BaseDir -Recurse -File | Measure-Object Length -Sum).Sum) / 1KB)

$UninstallCmd = 'powershell.exe -ExecutionPolicy Bypass -NoProfile -Command "`$ErrorActionPreference = ''SilentlyContinue''; Stop-Process -Name applocker,runtimesvc -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2; schtasks.exe /Delete /TN ''App Locker - Interactive User'' /F 2>`$null; Remove-ItemProperty -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'' -Name ''AppLockerWatchdog'' -ErrorAction SilentlyContinue; Remove-Item -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppLocker'' -Recurse -Force -ErrorAction SilentlyContinue; Remove-Item -Path ''C:\Windows\System32\Acceleron\Applocker'' -Recurse -Force -ErrorAction SilentlyContinue"'

$BlockUninstallCmd = 'powershell.exe -ExecutionPolicy Bypass -NoProfile -Command "`$ErrorActionPreference = ''SilentlyContinue''; Stop-Process -Name appblocker,svcapp -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2; schtasks.exe /Delete /TN ''App Blocker - Interactive User'' /F 2>`$null; Remove-ItemProperty -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'' -Name ''AppBlockerWatchdog'' -ErrorAction SilentlyContinue; Remove-Item -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppBlocker'' -Recurse -Force -ErrorAction SilentlyContinue; Remove-Item -Path ''C:\Windows\System32\Acceleron\Appblocker'' -Recurse -Force -ErrorAction SilentlyContinue"'


$PinnedThumbprint   = "C9C559D901C9B31C90AF64D0D20A091013A3D4C3"

$IsSystem           = ([Security.Principal.WindowsIdentity]::GetCurrent().IsSystem)
$IsAdmin            = ([Security.Principal.WindowsPrincipal] `
                      [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

Remove-Item $LogFile -Force -ErrorAction SilentlyContinue

# ============================================================
# ENSURE BASE DIRECTORY
# ============================================================

# Create base directory if not exists
if (-not (Test-Path $BaseDir)) {
    New-Item -Path $BaseDir -ItemType Directory -Force | Out-Null
}

# Create certificate directory if not exists
if (-not (Test-Path $CertDir)) {
    New-Item -Path $CertDir -ItemType Directory -Force | Out-Null
}

if (-not (Test-Path $LogFile)) {
    New-Item -Path $LogFile -ItemType File | Out-Null
	    $acl = Get-Acl $LogFile
        $rule = New-Object System.Security.AccessControl.FileSystemAccessRule("Everyone", "FullControl", "Allow")
        $acl.SetAccessRule($rule)
    Set-Acl -Path $LogFile -AclObject $acl
}

# ============================================================
# CLEAN OLD TASKS (SAFE)
# ============================================================
# STOP APPLOCKER PROCESSES
$t = 0
do {
   Get-Process -Name applocker,runtimesvc -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
   Start-Sleep -Milliseconds 500
   $t++
} while ((Get-Process -Name applocker,runtimesvc -ErrorAction SilentlyContinue) -and $t -lt 20)

# STOP APPIDSVC
Stop-Service -Name AppIDSvc -Force -ErrorAction SilentlyContinue
$Service = Get-Service -Name AppIDSvc -ErrorAction SilentlyContinue
if ($Service) { $Service.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Stopped, [TimeSpan]::FromSeconds(30)) }

# DISABLE APPIDSVC
Set-Service -Name AppIDSvc -StartupType Disabled -ErrorAction SilentlyContinue
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\AppIDSvc" -Name "Start" -Value 4 -ErrorAction SilentlyContinue

# REMOVE APPLOCKER FILES
Remove-Item -Path $AppLockerPath,$WatchDogPath,$CertPath -Force -ErrorAction SilentlyContinue

